catalog_script_client.script:
function onLoad() {

    var $ = this.jQuery;
    var userLang = g_lang;

    setTimeout(function() {

        var $headers = $(".container-caption.form-container-caption.ng-scope");
        if ($headers.length > 0) {
            $headers.each(function() {
                var $header = $(this);
                if ($header.text().trim() === "Section 1") {
                    $header.text("Employee Information");
                }
            });
        }
        $(".container-caption.form-container-caption.ng-scope").css({
            "width": "100%",
            "background-color": "rgb(66, 122, 38)",
            "color": "rgb(255, 255, 255)",
            "border": "1px solid rgb(66, 122, 38)",
            "padding": "14px 10px 10px",
            "margin-bottom": "10px",
            "position": "relative",
            "cursor": "pointer",
            "transition": "background-color, color 0.25s",
            "font-size": "1.8rem"
        });
    }, 100);

    if (userLang === "en") {
        g_form.setLabelOf('contact_information', 'Preferred contact information (personal email, cell phone number)');
    } else { 
        g_form.setLabelOf('contact_information', 
            'Coordonnées privilégiées (courriel personnel, numéro de téléphone cellulaire)');
    }
}
